const importId = '0000000000000000000000d4', actor = '0000000000000000000000e1';
const start = new Date('2026-10-19T00:00:00Z');
const slot = (index: number) => `0000000a-0000-4000-a000-${String(index + 1).padStart(12, '0')}`;
const mbid = (index: number) => `0000000d-0000-4000-8000-${String(index).padStart(12, '0')}`;
const tags = (extra: Record<string, unknown> = {}) => ({ version: 2, title: null, album: null, artists: [], albumArtists: [], label: null, year: null, discNumber: null, trackNumber: null,
    durationMs: null, identifiers: { barcode: null, catalogNumber: null, isrc: null, musicBrainzReleaseId: null }, flagged: [], ...extra });
/** An import of `count` confirmed files chosen in a folder, each with the given version-2 evidence, and an empty Draft v2. */
function project(count: number, evidence: (index: number) => Record<string, unknown>, rootLabel = 'Synthetic Folder'): AdminImportDocument {
    const manifest: ImportManifest = { rootLabel, files: Array.from({ length: count }, (_unused, index) => ({ slotId: slot(index), filename: `${index}.flac`, relativePath: `${rootLabel}/${index}.flac`, byteLength: 1 })) };
    const assets = manifest.files.map((file, index) => ({ slotId: file.slotId, operationId: mbid(500 + index), state: 'ready', sha256: 'a'.repeat(64), duration: null, tags: evidence(index) }) as unknown as ImportAsset);
    return { _id: new ObjectId(importId), purpose: 'import', draftVersion: 2, draft: defaultDraftV2(manifest), draftOrigins: {}, manifest, media: { assets },
        revision: 3, valueRevision: 0, decisions: [], suggestions: [], receipts: [], updatedAt: new Date(0) } as unknown as AdminImportDocument;
}
/** The run an upload (or, with `submitted`, a submission) starts for `doc`, or one with the given queries. */
function runOf(doc: AdminImportDocument, options: { submitted?: MetadataLookupSubmission; queries?: PlannedLookupQuery[] } = {}): MetadataLookupRecord {
    const planned = planImportLookup(doc, { folderAvailable: true, ...(options.submitted ? { submitted: options.submitted } : {}) });
    return startLookupRun(null, { importId: doc._id, actorId: actor, grantSource: options.submitted ? 'submit' : 'upload', operationId: mbid(600), automatic: !options.submitted,
        input: planned.input, queries: options.queries ?? planned.plan.queries, fileSet: importLookupFileSet(doc), now: start });
}
const json = (url: string, body: unknown): LookupExchange => ({ url, status: 200, headers: { 'content-type': 'application/json' }, body });
const searchUrl = (query: MusicBrainzReleaseQuery) => musicBrainzUrls.releaseSearch(query).href;
/** A release search answer: each release with its reported track count, and the hit count it reports (the returned ones by default). */
const searchAnswer = (query: MusicBrainzReleaseQuery, releases: [string, number?][], count = releases.length) => json(searchUrl(query), { count, offset: 0,
    releases: releases.map(([id, trackCount], index) => ({ id, title: `Synthetic Release ${index}`, score: 100 - index, ...(trackCount === undefined ? {} : { 'track-count': trackCount }) })) });
const releaseAnswer = (id: string, lengths: number[]) => json(musicBrainzUrls.release(id).href, { id, title: 'Synthetic Album', media: [{ position: 1, format: 'CD',
    tracks: lengths.map((length, index) => ({ position: index + 1, number: String(index + 1), title: `Synthetic Track ${index + 1}`, length, recording: { id: mbid(900 + index), length } })) }] });
/**
 * MusicBrainz over fixture exchanges, and iTunes over its own (`itunes`) or, by default, an iTunes client that answers nothing (so a
 * run without a MusicBrainz match passes through an empty iTunes stage); `itunesCalls` records what that default client was asked.
 */
const clientOf = (exchanges: LookupExchange[], itunes?: LookupExchange[]) => {
    const fixture = fixtureTransport(exchanges), itunesCalls: string[] = [];
    const replayed = itunes ? itunesFixtureClient(itunes) : null;
    return { musicBrainz: createMusicBrainzClient({ gate: immediateGate(), transport: fixture.transport, sleep: async () => undefined, configuration: availableLookupConfiguration }),
        itunes: replayed?.itunes ?? emptyItunesClient(itunesCalls), requests: fixture.requests, itunesRequests: replayed?.requests ?? [], itunesCalls };
};
type Client = ReturnType<typeof clientOf>;
/** Drives a run as the worker would, waiting out each automatic retry on a virtual clock, until it ends. */
async function drive(record: MetadataLookupRecord, doc: AdminImportDocument, client: Client, modes: string[] = []) {
    let now = start, result: LookupStepResult | null = null, next = record;
    for (let steps = 0; steps < 100; steps++) {
        const proceeded = proceedLookupRun(next, doc, result, now);
        next = proceeded.next;
        if (!proceeded.step.action) {
            if (next.state !== 'retrying') return next;
            now = next.retryAt!; result = null; continue;
        }
        modes.push(proceeded.step.mode);
        result = await performLookupStep(client, proceeded.step.action, proceeded.step.mode);
    }
    throw new Error('the run did not end');
}
/** Searches and release lookups sent; artist and label alias lookups are counted apart (`aliasLookups`). */
const sent = (client: Client) => ({ searches: client.requests.filter(request => !/\/ws\/2\/(?:release|artist|label)\/[0-9a-f-]{36}\?/.test(request.url)).length,
    details: client.requests.filter(request => /\/ws\/2\/release\/[0-9a-f-]{36}\?/.test(request.url)).length });
const aliasLookups = (client: Client) => client.requests.filter(request => /\/ws\/2\/(?:artist|label)\/[0-9a-f-]{36}\?/.test(request.url)).map(request => request.url);
const one = (index: number) => tags({ album: 'Synthetic Album', albumArtists: ['Synthetic Ensemble'], durationMs: [200_000, 210_000][index] });

test('fallback queries are sent together only when the searches before them found nothing; a skipped folder fallback spends no folder allowance', async () => {
    const doc = project(2, index => tags({ durationMs: [200_000, 210_000][index] }), 'Synthetic Artist - Synthetic Folder (2013 Remaster)');
    const record = runOf(doc);
    const queries = record.queries.map(query => [(query as { query: MusicBrainzReleaseQuery }).query, (query as { fallback?: true }).fallback === true]);
    // The folder's split respelled is the only fallback: its whole name names no release.
    assert.deepEqual(queries, [[{ artist: 'Synthetic Artist', release: 'Synthetic Folder (2013 Remaster)' }, false],
        [{ release: 'Synthetic Artist - Synthetic Folder (2013 Remaster)' }, false], [{ artist: 'Synthetic Artist', release: 'Synthetic Folder' }, true]]);
    // Both searches find nothing, so the normalized fallback is sent, and finds the release.
    const client = clientOf([searchAnswer({ artist: 'Synthetic Artist', release: 'Synthetic Folder (2013 Remaster)' }, []),
        searchAnswer({ release: 'Synthetic Artist - Synthetic Folder (2013 Remaster)' }, []), searchAnswer({ artist: 'Synthetic Artist', release: 'Synthetic Folder' }, [[mbid(1), 2]]),
        releaseAnswer(mbid(1), [200_000, 210_000])]);
    const done = await drive(record, doc, client);
    assert.deepEqual([done.state, done.outcome, done.queryIndex, done.folderUsed, done.searchComplete, sent(client), done.ranking!.preselection?.basis],
        ['complete', 'candidates', 3, true, true, { searches: 3, details: 1 }, 'onlyMatchingGroup']);
    // Album tags spelled "Sound Track": once the fallbacks start they are all sent, since one spelling alone may find fewer editions.
    const album = project(2, index => tags({ album: 'Synthetic Sound Track', albumArtists: ['Synthetic Ensemble'], durationMs: [200_000, 210_000][index] }));
    const respelled = runOf(album);
    assert.deepEqual(respelled.queries.map(query => [(query as { query: MusicBrainzReleaseQuery }).query, (query as { fallback?: true }).fallback === true]), [
        [{ release: 'Synthetic Sound Track', artist: 'Synthetic Ensemble' }, false], [{ release: 'Synthetic Sound Track' }, false],
        [{ release: 'Synthetic Soundtrack', artist: 'Synthetic Ensemble' }, true], [{ release: 'Synthetic Soundtrack' }, true]]);
    const both = clientOf([searchAnswer({ release: 'Synthetic Sound Track', artist: 'Synthetic Ensemble' }, []), searchAnswer({ release: 'Synthetic Sound Track' }, []),
        searchAnswer({ release: 'Synthetic Soundtrack', artist: 'Synthetic Ensemble' }, [[mbid(1), 2]]), searchAnswer({ release: 'Synthetic Soundtrack' }, [[mbid(1), 2], [mbid(2), 2]]),
        releaseAnswer(mbid(1), [200_000, 210_000]), releaseAnswer(mbid(2), [200_000, 210_000])]);
    const together = await drive(respelled, album, both);
    assert.deepEqual([together.queryIndex, together.candidates.length, sent(both), together.ranking!.groups.length], [4, 2, { searches: 4, details: 2 }, 1]);
    // Without a candidate every fallback is sent, and the run finds no release.
    const empty = clientOf(record.queries.map(query => searchAnswer((query as { query: MusicBrainzReleaseQuery }).query, [])));
    assert.deepEqual([(await drive(record, doc, empty)).outcome, sent(empty).searches], ['noRelease', 3]);
    // A candidate known as the fallbacks start skips them all; a skipped folder fallback is never handed out, so the allowance stays unspent.
    const folderFallback: PlannedLookupQuery = { kind: 'musicBrainzReleaseSearch', query: { release: 'Synthetic Folder' }, basis: 'folder', fallback: true };
    const identified = runOf(doc, { queries: [{ kind: 'musicBrainzRelease', releaseId: mbid(2), basis: 'releaseId' }, folderFallback, { ...folderFallback, query: { release: 'Other' } }] });
    const byId = clientOf([releaseAnswer(mbid(2), [200_000, 210_000])]);
    const kept = await drive(identified, doc, byId);
    assert.deepEqual([kept.state, kept.folderUsed, kept.queryIndex, byId.requests.length], ['complete', false, 3, 1]);
});

test('a comparison is partial when a search returned fewer hits than it reported, the bound left a hit out or stopped a planned query, a search was refused, or the record predates the field', async () => {
    const doc = project(2, one), record = runOf(doc);
    const credited = { release: 'Synthetic Album', artist: 'Synthetic Ensemble' }, bare = { release: 'Synthetic Album' };
    // One matching release among others with three tracks that never match.
    const details = (count: number) => [releaseAnswer(mbid(1), [200_000, 210_000]), ...Array.from({ length: count }, (_unused, index) => releaseAnswer(mbid(10 + index), [1000, 1000, 1000]))];
    const others = (count: number, from = 10): [string, number][] => Array.from({ length: count }, (_unused, index) => [mbid(from + index), 2]);
    const outcome = async (exchanges: LookupExchange[], base = record) => {
        const client = clientOf(exchanges), done = await drive(base, doc, client);
        return { done, client, partial: done.ranking!.disclosure.partialComparison, preselected: done.ranking!.preselection?.candidateKey ?? null, groups: done.ranking!.groups.length };
    };
    const complete = await outcome([searchAnswer(credited, [[mbid(1), 2]]), searchAnswer(bare, [[mbid(1), 2]]), ...details(0)]);
    assert.deepEqual([complete.done.searchComplete, complete.partial, complete.preselected, sent(complete.client)], [true, false, `musicbrainz:${mbid(1)}`, { searches: 2, details: 1 }]);
    // A search that reported more hits than it returned.
    const truncated = await outcome([searchAnswer(credited, [[mbid(1), 2]], 7), searchAnswer(bare, [[mbid(1), 2]]), ...details(0)]);
    assert.deepEqual([truncated.done.searchComplete, truncated.partial, truncated.groups, truncated.preselected], [false, true, 1, null]);
    // The bound left out a release a search offered.
    const leftOut = await outcome([searchAnswer(credited, [[mbid(1), 2], ...others(23)]), searchAnswer(bare, others(3, 40)), ...details(23), releaseAnswer(mbid(40), [1000, 1000, 1000])]);
    assert.deepEqual([leftOut.done.candidates.length, leftOut.done.searchComplete, leftOut.partial, leftOut.preselected], [25, false, true, null]);
    // The bound stopped a planned query before it was sent.
    const stopped = await outcome([searchAnswer(credited, [[mbid(1), 2], ...others(24)]), ...details(24)]);
    assert.deepEqual([stopped.done.queryIndex, stopped.done.searchComplete, stopped.partial, stopped.preselected, sent(stopped.client)], [1, false, true, null, { searches: 1, details: 25 }]);
    // A refused search.
    const first = proceedLookupRun(record, doc, null, start);
    const refused = proceedLookupRun(first.next, doc, { kind: 'refused', action: first.step.action! }, start);
    assert.deepEqual([refused.next.queryIndex, refused.next.searchComplete], [1, false]);
    // A record from a release before the field stays partial, even with complete searches.
    const legacy = { ...record } as Partial<MetadataLookupRecord>;
    delete legacy.searchComplete;
    const old = await outcome([searchAnswer(credited, [[mbid(1), 2]]), searchAnswer(bare, [[mbid(1), 2]]), ...details(0)], legacy as MetadataLookupRecord);
    assert.deepEqual([old.done.searchComplete, old.partial, old.preselected], [false, true, null]);
    // Its only matching group is offered, not applied: one group is no tie, so publication never waits for it.
    assert.deepEqual(lookupAnswersNeeded(old.done, doc, { append: false }), { tie: false, conflicts: [] });
});

test('a release that cannot match never makes a comparison partial: one the bound left out that reported another track count, one that no longer exists, and one whose details failed after reporting another count', async () => {
    const doc = project(2, one), record = runOf(doc);
    const credited = { release: 'Synthetic Album', artist: 'Synthetic Ensemble' }, bare = { release: 'Synthetic Album' };
    const others = (count: number, from: number): [string, number][] => Array.from({ length: count }, (_unused, index) => [mbid(from + index), 2]);
    const details = (ids: string[]) => ids.map(id => releaseAnswer(id, id === mbid(1) ? [200_000, 210_000] : [1000, 1000]));
    // 25 plausible releases fill the bound with the last search; the 3-track release it left out cannot match two files.
    const plausible = [mbid(1), ...others(24, 10).map(([id]) => id)];
    const implausibleLeftOut = clientOf([searchAnswer(credited, [[mbid(1), 2], ...others(19, 10)]), searchAnswer(bare, [...others(5, 29), [mbid(80), 3]]), ...details(plausible)]);
    const complete = await drive(record, doc, implausibleLeftOut);
    assert.deepEqual([complete.candidates.length, complete.searchComplete, complete.ranking!.disclosure.partialComparison, complete.ranking!.preselection?.basis, sent(implausibleLeftOut)],
        [25, true, false, 'onlyMatchingGroup', { searches: 2, details: 25 }]);
    // A left-out release of unknown track count could match: the comparison is partial.
    const unknownLeftOut = clientOf([searchAnswer(credited, [[mbid(1), 2], ...others(19, 10)]), searchAnswer(bare, [...others(5, 29), [mbid(81)]]), ...details(plausible)]);
    const partial = await drive(record, doc, unknownLeftOut);
    assert.deepEqual([partial.searchComplete, partial.ranking!.disclosure.partialComparison, partial.ranking!.preselection], [false, true, null]);
    // A release that no longer exists (404) and a 3-track release whose details stay unavailable through every retry cannot
    // match either: the run completes (unavailable details reported) and still preselects the only matching group.
    const gone = { url: musicBrainzUrls.release(mbid(2)).href, status: 404, headers: { 'content-type': 'application/json' }, body: { error: 'Not Found' } };
    const incomplete = clientOf([searchAnswer(credited, [[mbid(1), 2], [mbid(3), 3]]), searchAnswer(bare, [[mbid(2)]]), releaseAnswer(mbid(1), [200_000, 210_000]), gone]);
    const ended = await drive(record, doc, incomplete);
    assert.deepEqual([ended.state, ended.issue, ended.candidates.map(candidate => [candidate.releaseId, candidate.details]), ended.searchComplete,
        ended.ranking!.disclosure.partialComparison, ended.ranking!.preselection?.candidateKey],
        ['complete', 'sourceUnavailable', [[mbid(1), 'fetched'], [mbid(3), 'failed'], [mbid(2), 'missing']], true, false, `musicbrainz:${mbid(1)}`]);
    // The same failure for a release reporting two tracks could hide a match: partial, nothing preselected.
    const hidden = clientOf([searchAnswer(credited, [[mbid(1), 2], [mbid(3), 2]]), searchAnswer(bare, []), releaseAnswer(mbid(1), [200_000, 210_000])]);
    const hiding = await drive(record, doc, hidden);
    assert.deepEqual([hiding.ranking!.disclosure.partialComparison, hiding.ranking!.preselection, lookupAnswersNeeded(hiding, doc, { append: false }).tie], [true, null, false]);
});

test('details of releases whose reported track count can match are fetched first', async () => {
    const doc = project(2, one), record = runOf(doc);
    // The first search offers a 3-track and an unknown-count release (admitted first, since it may match); the second a 2-track
    // one, whose details are fetched before the 3-track release's although it was found later.
    const client = clientOf([searchAnswer({ release: 'Synthetic Album', artist: 'Synthetic Ensemble' }, [[mbid(1), 3], [mbid(2)]]),
        searchAnswer({ release: 'Synthetic Album' }, [[mbid(3), 2]]), releaseAnswer(mbid(3), [200_000, 210_000]), releaseAnswer(mbid(1), [1000, 1000, 1000]),
        releaseAnswer(mbid(2), [1000, 1000])]);
    const done = await drive(record, doc, client);
    const fetched = client.requests.map(request => /release\/([0-9a-f-]{36})\?/.exec(request.url)?.[1]).filter(Boolean);
    assert.deepEqual([fetched, done.candidates.map(candidate => candidate.releaseId)], [[mbid(2), mbid(3), mbid(1)], [mbid(2), mbid(1), mbid(3)]]);
});

test('a 503/429 is busy and retried after its Retry-After within 2–10 s, later after 2 and 5 minutes, then unavailable; a gate busy or unavailable failure keeps 30 s', async () => {
    // The smoke's submitted run: its first request (busy mode) meets a 503 with Retry-After: 0.
    const doc = project(2, () => tags({ durationMs: 200_000 })), submitted = runOf(doc, { submitted: { kind: 'album', text: 'Synthetic Album' } });
    assert.deepEqual(submitted.queries.map(query => (query as { query: MusicBrainzReleaseQuery }).query), [{ release: 'Synthetic Album' }]);
    const throttled = clientOf([...loadLookupFixture('musicbrainz/synthetic-503-retry-after-0-then-200.json').exchanges, releaseAnswer(mbid(1), [200_000, 200_000])]);
    const first = proceedLookupRun(submitted, doc, null, start);
    assert.equal(first.step.mode, 'busy');
    const failure = await performLookupStep(throttled, first.step.action!, first.step.mode);
    assert.deepEqual(failure, { kind: 'failed', source: 'musicbrainz', failure: 'rateLimited', retryAfterMs: 1000 });
    const waiting = proceedLookupRun(first.next, doc, failure, start).next;
    assert.deepEqual([waiting.state, waiting.issue, waiting.retryAt!.getTime() - start.getTime(), waiting.attempts], ['retrying', 'sourceBusy', 2_000, { musicbrainz: 1, itunes: 0 }]);
    const modes: string[] = [];
    const done = await drive(waiting, doc, throttled, modes);
    assert.deepEqual([done.state, done.issue, done.outcome, modes, throttled.requests.length], ['complete', null, 'candidates', ['wait', 'wait'], 3]);

    // Failures in a row: the first throttled one follows its Retry-After (clamped), later ones 2 and 5 minutes, then the run ends busy.
    const automatic = runOf(project(2, one)), action = proceedLookupRun(automatic, doc, null, start).next;
    const fail = (record: MetadataLookupRecord, result: LookupStepResult, now = start) => proceedLookupRun(record, doc, result, now).next;
    const limited = (retryAfterMs: number | null): LookupStepResult => ({ kind: 'failed', source: 'musicbrainz', failure: 'rateLimited', retryAfterMs });
    let record = fail(action, limited(7000));
    const delays: [string, string | null, number | null][] = [[record.state, record.issue, record.retryAt!.getTime() - start.getTime()]];
    for (let attempt = 0; attempt < 2; attempt++) {
        record = fail(record, limited(45_000));
        delays.push([record.state, record.issue, record.retryAt ? record.retryAt.getTime() - start.getTime() : null]);
    }
    assert.deepEqual(delays, [['retrying', 'sourceBusy', 7_000], ['retrying', 'sourceBusy', 120_000], ['retrying', 'sourceBusy', 300_000]]);
    // Exhausted while searching: MusicBrainz is asked nothing more and the iTunes stage starts (`searchUnavailable`); finding no
    // iTunes-only candidate, the run ends unavailable with MusicBrainz's issue, never "no release", and is never ranked.
    const exhaustedStep = proceedLookupRun(record, doc, limited(45_000), start);
    assert.deepEqual([exhaustedStep.next.state, exhaustedStep.next.exhausted, exhaustedStep.next.itunesStage?.reason, exhaustedStep.next.queryIndex, exhaustedStep.step.action?.kind],
        ['running', { musicbrainz: 'sourceBusy' }, 'searchUnavailable', automatic.queries.length, 'itunes']);
    const itunesOnly = clientOf([]);
    record = await drive(exhaustedStep.next, doc, itunesOnly);
    assert.deepEqual([record.state, record.issue, record.retryAt, record.ranking, record.outcome, record.attempts, itunesOnly.requests.length, itunesOnly.itunesCalls],
        ['unavailable', 'sourceBusy', null, null, null, { musicbrainz: 4, itunes: 0 }, 0, ['album us Synthetic Album Synthetic Ensemble', 'album jp Synthetic Album Synthetic Ensemble']]);
    assert.equal(fail(action, limited(45_000)).retryAt!.getTime() - start.getTime(), METADATA_LOOKUP_JOB_LIMITS.rateLimitedRetryMs.maximum);
    // A gate refusal is busy and an outage unavailable: both keep 30 seconds (or a longer Retry-After of at most a minute).
    for (const [result, issue, delay] of [[{ kind: 'failed', source: 'musicbrainz', failure: 'busy', retryAfterMs: 1000 }, 'sourceBusy', 30_000],
        [{ kind: 'failed', source: 'musicbrainz', failure: 'busy', retryAfterMs: 45_000 }, 'sourceBusy', 45_000],
        [{ kind: 'failed', source: 'musicbrainz', failure: 'unavailable', retryAfterMs: null }, 'sourceUnavailable', 30_000]] as const) {
        const next = fail(action, result);
        assert.deepEqual([next.state, next.issue, next.retryAt!.getTime() - start.getTime()], ['retrying', issue, delay], JSON.stringify(result));
    }
    // A retry past the grant counts as exhausted, the throttled one and the 30-second one alike, so a run never blocks past its grant
    // (the worker stops it once the grant expires); MusicBrainz is exhausted with the issue it failed with.
    const late = fail(action, limited(9000), new Date(action.grantExpiresAt.getTime() - 5000));
    assert.deepEqual([late.exhausted, late.retryAt, late.itunesStage?.reason], [{ musicbrainz: 'sourceBusy' }, null, 'searchUnavailable']);
    for (const [failure, issue] of [['unavailable', 'sourceUnavailable'], ['busy', 'sourceBusy']] as const) {
        const ended = fail(action, { kind: 'failed', source: 'musicbrainz', failure, retryAfterMs: null }, new Date(action.grantExpiresAt.getTime() - 10_000));
        assert.deepEqual([ended.exhausted, ended.retryAt, ended.attempts], [{ musicbrainz: issue }, null, { musicbrainz: 1, itunes: 0 }], failure);
    }
});

const recorded = new Map<string, MusicBrainzRelease>([...loadLookupFixtures('musicbrainz').entries()].filter(([name]) => /^release-[0-9a-f-]{36}\.json$/.test(name))
    .map(([, file]) => parseMusicBrainzRelease(file.exchanges.at(-1)!.body)).map(release => [release.releaseId, release]));
const fixture = (prefix: string) => [...recorded.values()].find(release => release.releaseId.startsWith(prefix))!;
const blueArchiveTag = 'Blue Archive Original Sound Track Vol.1 ~Longing for the memorable days~';

test('Blue Archive tags spelled Sound Track: both exact searches are empty, so the normalized fallbacks are sent together and find the CD and digital editions as a tie', async () => {
    const cd = fixture('8baecda4'), lengths = cd.media.flatMap(medium => medium.tracks.map(track => track.lengthMs!));
    const normalized = 'Blue Archive Original Soundtrack Vol.1 ~Longing for the memorable days~';
    const recordedAnswers = () => [...loadLookupFixture('musicbrainz/release-search-blue-archive-sound-track.json').exchanges,
        ...loadLookupFixture('musicbrainz/release-search-blue-archive-normalized.json').exchanges,
        ...loadLookupFixture('musicbrainz/release-8baecda4-f155-40f6-a173-8f6b98cede5b.json').exchanges, ...loadLookupFixture('musicbrainz/release-8f032fff-c63f-4512-973a-758d6d0da2bd.json').exchanges];
    const outcome = async (albumArtists: string[], extra: LookupExchange[] = []) => {
        const doc = project(39, index => tags({ album: blueArchiveTag, albumArtists, durationMs: lengths[index] + ((index * 7919) % 801) - 400 }));
        const record = runOf(doc), client = clientOf([...recordedAnswers(), ...extra]);
        const done = await drive(record, doc, client);
        return { doc, record, done, client };
    };
    // The album artist tag as the label it really is: every answer was recorded.
    const label = await outcome(['株式会社Yostar']);
    assert.deepEqual(label.record.queries.map(query => (query as { query: MusicBrainzReleaseQuery }).query), [{ release: blueArchiveTag, label: '株式会社Yostar' }, { release: blueArchiveTag },
        { release: normalized, label: '株式会社Yostar' }, { release: normalized }]);
    // The credited names: the respelled credited search was never recorded, so it is answered both ways; the bare respelled search
    // is sent with it either way, so the comparison is the same.
    const credited = { release: normalized, artist: 'ミツキヨ、KARUT、Nor' };
    const subtitleByCredit = loadLookupFixture('musicbrainz/release-search-blue-archive-subtitle.json').exchanges[1].body as { releases: unknown[] };
    const runs = [label, await outcome(['ミツキヨ、KARUT、Nor'], [searchAnswer(credited, [])]),
        await outcome(['ミツキヨ、KARUT、Nor'], [json(searchUrl(credited), { count: 1, offset: 0, releases: subtitleByCredit.releases })])];
    for (const { done, doc, client } of runs) {
        assert.deepEqual([done.state, done.outcome, done.searchComplete, done.queryIndex, sent(client)], ['complete', 'candidates', true, 4, { searches: 4, details: 2 }]);
        assert.ok(decodeURIComponent(client.requests[3].url.replace(/\+/g, ' ')).includes('query=release:"Blue Archive Original Soundtrack Vol.1 \\~Longing for the memorable days\\~"&'));
        assert.deepEqual([done.ranking!.groups.length, done.ranking!.preselection, done.ranking!.disclosure.partialComparison, lookupAnswersNeeded(done, doc, { append: false })],
            [2, null, false, { tie: true, conflicts: [] }]);
    }
});

test('Hotel California at the 100-release page: nine-track editions are admitted and fetched first, the bound stops the bare search, and the digital edition ties with the European CD', async () => {
    const digital = fixture('fa7d3357'), lengths = digital.media[0].tracks.map(track => track.lengthMs!);
    const doc = project(9, index => tags({ album: 'Hotel California', albumArtists: ['Eagles'], artists: ['Eagles'], durationMs: lengths[index] }));
    const record = runOf(doc), client = clientOf(hotelCaliforniaExchanges());
    assert.deepEqual(record.queries.map(query => (query as { query: MusicBrainzReleaseQuery }).query), [{ release: 'Hotel California', artist: 'Eagles' }, { release: 'Hotel California' }]);
    const done = await drive(record, doc, client);
    const searches = sent(client);
    // The derived page offers 26 releases: its 20 nine-track ones first, then five others; the 18-track one left out cannot match.
    assert.deepEqual([done.state, done.queryIndex, done.searchComplete, done.candidates.length, searches], ['complete', 1, false, 25, { searches: 1, details: 25 }]);
    assert.ok(done.candidates.slice(0, 20).every(candidate => candidate.summary?.trackCount === 9) && done.candidates.some(candidate => candidate.releaseId.startsWith('fa7d3357')));
    const fetched = client.requests.map(request => /release\/([0-9a-f-]{36})\?/.exec(request.url)?.[1]).filter(Boolean);
    assert.deepEqual(fetched.slice(0, 20), done.candidates.slice(0, 20).map(candidate => candidate.releaseId));
    assert.ok(searches.searches <= METADATA_LOOKUP_LIMITS.plannedQueries && searches.details <= METADATA_LOOKUP_JOB_LIMITS.candidates);
    const matching = done.ranking!.candidates.filter(candidate => candidate.status === 'matching').map(candidate => candidate.releaseId.slice(0, 8)).sort();
    assert.deepEqual([matching, done.ranking!.groups.length, done.ranking!.preselection, done.ranking!.disclosure.partialComparison], [['cb961c6b', 'fa7d3357'], 2, null, true]);
    assert.deepEqual(lookupAnswersNeeded(done, doc, { append: false }), { tie: true, conflicts: [] });
    assert.equal(client.requests.some(request => request.url.includes('tracks')), false, 'the file count is never sent');

    // The live smoke's case: a page that offered 25 of 83 hits (the recorded first page) leaves the European CD as the only
    // matching group, which is offered but never preselected or needed as an answer.
    const recordedPage = { ...loadLookupFixture('musicbrainz/release-search-hotel-california.json').exchanges[0], url: searchUrl({ release: 'Hotel California', artist: 'Eagles' }) };
    const truncated = clientOf([recordedPage, ...hotelCaliforniaExchanges().filter(exchange => !exchange.url.includes('/ws/2/release?query='))]);
    const smoke = await drive(record, doc, truncated);
    assert.deepEqual([smoke.searchComplete, sent(truncated), smoke.ranking!.groups.map(group => group.representativeKey.slice(12, 20)), smoke.ranking!.preselection,
        smoke.ranking!.disclosure.partialComparison, lookupAnswersNeeded(smoke, doc, { append: false })],
        [false, { searches: 1, details: 25 }, ['cb961c6b'], null, true, { tie: false, conflicts: [] }]);
});

